-- ---------------------------------------------------------- localities
insert into localities (slug, name, city, blurb, description, highlights, price_band, growth, sort_order, state) values
  ('dwarka-expressway', 'Dwarka Expressway', 'Gurugram', 'The 29-km Northern Peripheral Road linking Dwarka to NH-48 — now Gurugram''s deepest supply corridor.', 'Dwarka Expressway (NH-248BB) is the single most consequential infrastructure project in Gurugram''s recent history. With the full carriageway and the Delhi stretch now operational, travel to IGI Airport collapses to roughly 20 minutes and Dwarka Sub-City becomes directly accessible. Sectors 99 to 115 carry the bulk of new launches, with a proposed metro extension and the Gurugram–Dwarka ISBT further strengthening the corridor. The trade-off buyers should understand: supply here is deep, so developer credibility and tower positioning matter more than the postcode alone.', '{"Direct 20-minute access to IGI Airport Terminal 3","Operational 8-lane expressway with dedicated service roads","Proposed metro extension along the corridor","Dense cluster of Grade-A developer launches in Sectors 99-115","Close to Dwarka Sub-City social infrastructure"}', '₹11K - ₹18.5K', 'High appreciation potential', 0, 'published')
