insert into localities (slug, name, city, blurb, description, highlights, price_band, growth, sort_order, state) values
  ('golf-course-road', 'Golf Course Road', 'Gurugram', 'Gurugram''s established luxury spine — the highest per-square-foot address in the city.', 'Golf Course Road is Gurugram''s most mature premium corridor. A 16-lane signal-free stretch with the Rapid Metro running alongside, it concentrates the city''s best private schools, hospitals, luxury retail and corporate offices within a two-kilometre band. Inventory is scarce and almost entirely resale or redevelopment, which keeps capital values resilient through market cycles. This is the corridor for buyers prioritising certainty of location over launch-stage pricing.', '{"Signal-free 16-lane carriageway with Rapid Metro connectivity","Highest capital values in Gurugram","Walk-to-work access to DLF Cyber City and Cyber Hub","Established schools, hospitals and luxury retail","Scarce land parcels sustain long-term pricing power"}', '₹22K - ₹45K', 'Stable, premium-resilient', 1, 'published')
