insert into localities (slug, name, city, blurb, description, highlights, price_band, growth, sort_order, state) values
  ('golf-course-extension-road', 'Golf Course Extension Road', 'Gurugram', 'The fast-maturing extension of the luxury spine, running from Sector 55 toward Sohna.', 'Golf Course Extension Road carries the premium positioning of Golf Course Road at a meaningfully lower entry point. Sectors 58 to 67 have absorbed a wave of luxury launches, and the corridor benefits from the Southern Peripheral Road interchange plus proximity to the Sohna Elevated Corridor. Social infrastructure has caught up considerably over the last five years, making this the most balanced risk-return corridor in the city for premium housing.', '{"Lower entry pricing than Golf Course Road, similar positioning","SPR and Sohna Elevated Corridor interchanges","Concentrated luxury and ultra-luxury launches in Sectors 58-67","Rapidly maturing retail and schooling infrastructure","Strong rental demand from corporate tenants"}', '₹16K - ₹28K', 'Strong momentum', 2, 'published')
