insert into localities (slug, name, city, blurb, description, highlights, price_band, growth, sort_order, state) values
  ('new-gurgaon', 'New Gurgaon', 'Gurugram', 'Sectors 76-95 along NH-48 — the value corridor with the widest configuration choice.', 'New Gurgaon spans the sectors flanking NH-48 beyond Hero Honda Chowk. It offers the city''s broadest range of formats — apartments, independent floors, plots and high-street retail — at entry points materially below the Golf Course corridors. The Pataudi Road widening, KMP Expressway access and the maturing IMT Manesar employment base underpin end-user demand here. Buyers get larger carpet areas per rupee, with the understanding that social infrastructure is still consolidating.', '{"Best area-per-rupee value in Gurugram","Direct NH-48 and KMP Expressway access","Widest format choice: apartments, floors, plots, SCO","Employment catchment from IMT Manesar","Active affordable and mid-premium housing supply"}', '₹8.5K - ₹14K', 'Value accumulation', 3, 'published')
