  growth = excluded.growth, sort_order = excluded.sort_order, state = excluded.state;
insert into localities (slug, name, city, blurb, description, highlights, price_band, growth, sort_order, state) values
  ('sohna-road', 'Sohna Road', 'Gurugram', 'A dense mixed-use corridor transformed by the Sohna Elevated Expressway.', 'Sohna Road connects Gurugram''s Subhash Chowk to the Sohna township and has been re-rated significantly by the elevated expressway, which cuts the drive to Sohna to under twenty minutes. The corridor carries a dense mix of mid-premium housing, office parks and high-street retail, with SCO plotted commercial emerging as the standout investment format in Sectors 67-70.', '{"Sohna Elevated Expressway dramatically improved travel times","Established office and retail catchment","Strong SCO plotted commercial opportunity","Direct connectivity to Golf Course Extension Road","Deep rental market from nearby office parks"}', '₹9.5K - ₹15.5K', 'Infrastructure-led re-rating', 4, 'published')
