insert into localities (slug, name, city, blurb, description, highlights, price_band, growth, sort_order, state) values
  ('dwarka-new-delhi', 'Dwarka, New Delhi', 'New Delhi', 'Delhi''s largest planned sub-city, now anchored by India International Convention Centre.', 'Dwarka is Asia''s largest planned residential sub-city and has entered a new growth phase with Yashobhoomi (India International Convention & Expo Centre), the Dwarka Expressway interchange and the airport express metro. Commercial inventory in Sectors 19B and 25 is scarce and institution-grade, making it a distinct opportunity set from Gurugram''s supply-heavy corridors.', '{"Yashobhoomi convention centre drives footfall and hospitality demand","Airport Express and Blue Line metro connectivity","DDA-planned sub-city with mature social infrastructure","Limited new commercial supply sustains pricing","Direct interchange with Dwarka Expressway"}', '₹15K - ₹32K', 'Institution-grade scarcity', 5, 'published')
