delete from project_configurations where project_id = (select id from projects where slug = 'godrej-vrikshya-sector-103-gurgaon');
insert into project_configurations (project_id, unit_type, area_sqft, price, sort_order)
  select id, '3 BHK', 1947, '₹3.60 Cr', 0 from projects where slug = 'godrej-vrikshya-sector-103-gurgaon';
insert into project_configurations (project_id, unit_type, area_sqft, price, sort_order)
  select id, '4 BHK', 3700, '₹5.66 Cr', 1 from projects where slug = 'godrej-vrikshya-sector-103-gurgaon';
delete from project_faqs where project_id = (select id from projects where slug = 'godrej-vrikshya-sector-103-gurgaon');
insert into project_faqs (project_id, question, answer, sort_order)
  select id, 'What makes Godrej Vrikshya unique?', 'Godrej Vrikshya Gurgaon stands out with its eco-friendly design, lush green spaces, and resort-style amenities. The project combines luxury, modern layouts, and sustainable living, offering residents a serene and sophisticated lifestyle along the Dwarka Expressway.', 0 from projects where slug = 'godrej-vrikshya-sector-103-gurgaon';
insert into project_faqs (project_id, question, answer, sort_order)
  select id, 'What types of apartments does Godrej Vrikshya offer?', 'Godrej Vrikshya Sector 103 offers 3 BHK and 4 BHK residences with spacious, well-ventilated interiors. The apartments feature premium finishes, contemporary designs, and thoughtfully planned layouts suitable for modern families seeking comfort and elegance.', 1 from projects where slug = 'godrej-vrikshya-sector-103-gurgaon';
insert into project_faqs (project_id, question, answer, sort_order)
  select id, 'Where can I view Godrej Vrikshya photos?', 'Godrej Vrikshya photos are available on the project website and in the Godrej Vrikshya brochure , showcasing apartment interiors, landscaped gardens, and world-class amenities for potential buyers to explore before visiting the site.', 2 from projects where slug = 'godrej-vrikshya-sector-103-gurgaon';
insert into project_faqs (project_id, question, answer, sort_order)
  select id, 'Can I check the Godrej Vrikshya floor plan before booking?', 'Yes, the Godrej Vrikshya floor plan is accessible online or via the sales team. It includes layouts ranging from 1,947 to 3,700 sq. ft., designed for functionality, ventilation, and modern family living.', 3 from projects where slug = 'godrej-vrikshya-sector-103-gurgaon';
insert into project_faqs (project_id, question, answer, sort_order)
  select id, 'What amenities are included in Godrej Vrikshya Gurgaon?', 'Godrej Vrikshya Gurgaon offers infinity pools, gyms, kids'' play areas, squash courts, landscaped gardens, jogging tracks, and eco-friendly features like rainwater harvesting, providing a luxury lifestyle in a green and sustainable environment.', 4 from projects where slug = 'godrej-vrikshya-sector-103-gurgaon';
insert into project_faqs (project_id, question, answer, sort_order)
  select id, 'Is Godrej Vrikshya Sector 103 Gurgaon a good investment?', 'Yes, Godrej Vrikshya Sector 103 Gurgaon offers strong investment potential due to its prime Dwarka Expressway location, connectivity to Delhi, and the trusted Godrej brand, ensuring long-term value appreciation for homeowners and investors.', 5 from projects where slug = 'godrej-vrikshya-sector-103-gurgaon';
insert into project_faqs (project_id, question, answer, sort_order)
  select id, 'How many towers and apartments are there in Godrej Vrikshya?', 'The project comprises 6 towers with around 621 luxury apartments. Godrej Vrikshya Sector 103 emphasizes low-density living, offering residents ample privacy, spacious homes, and well-planned common areas.', 6 from projects where slug = 'godrej-vrikshya-sector-103-gurgaon';
insert into project_faqs (project_id, question, answer, sort_order)
  select id, 'Where can I download the Godrej Vrikshya brochure?', 'The Godrej Vrikshya brochure can be downloaded from our website or obtained from the sales office. It provides detailed information about floor plans, amenities, layouts, pricing, and other project specifications.', 7 from projects where slug = 'godrej-vrikshya-sector-103-gurgaon';
delete from project_configurations where project_id = (select id from projects where slug = 'tulip-monsella-sector-53-gurgaon');
