delete from project_faqs where project_id = (select id from projects where slug = 'tulip-monsella-sector-53-gurgaon');
insert into project_faqs (project_id, question, answer, sort_order)
  select id, 'What is the location of Tulip Monsella?', 'Tulip Monsella Sector 53 is strategically located on Golf Course Road, Gurgaon, close to the Rapid Metro Station and major commercial hubs, offering excellent connectivity to NH-8, Cyber City, and other key destinations in Delhi NCR.', 0 from projects where slug = 'tulip-monsella-sector-53-gurgaon';
insert into project_faqs (project_id, question, answer, sort_order)
  select id, 'What types of apartments are available?', 'The project offers premium 3 BHK, 4 BHK, and 5 BHK apartments in Tulip Monsella Gurgaon , featuring spacious layouts, luxury finishes, double-height ceilings, and smart home features designed for modern urban living.', 1 from projects where slug = 'tulip-monsella-sector-53-gurgaon';
insert into project_faqs (project_id, question, answer, sort_order)
  select id, 'Is Tulip Monsella RERA approved?', 'Yes, Tulip Monsella Sector 53 is RERA-registered , ensuring full transparency, legal compliance, and timely possession, providing buyers peace of mind while investing in luxury apartments in Gurgaon.', 2 from projects where slug = 'tulip-monsella-sector-53-gurgaon';
insert into project_faqs (project_id, question, answer, sort_order)
  select id, 'Where can I get the Tulip Monsella brochure?', 'The official Tulip Monsella brochure can be downloaded online, offering detailed insights into floor plans, unit specifications, amenities, location advantages, and other essential project information.', 3 from projects where slug = 'tulip-monsella-sector-53-gurgaon';
insert into project_faqs (project_id, question, answer, sort_order)
  select id, 'What are the key amenities at Tulip Monsella?', 'Tulip Monsella Gurgaon provides world-class amenities including an infinity-edge swimming pool, clubhouse, spa, kids'' play area, jogging tracks, business lounge, and smart home automation, ensuring a luxurious and convenient lifestyle.', 4 from projects where slug = 'tulip-monsella-sector-53-gurgaon';
